// ============================================================================
// Generated by RaggieSoft Help Studio v0.6.0 — Learn Web Portal Controller
// Zero external dependencies: Theme Switcher, TOC Filter, Ctrl+K API Search,
// Code Copy & Syntax Highlighter, Scroll-Spy Outline, & Mobile Drawer Fallback.
// ============================================================================
const RSH_SEARCH_INDEX_URL = 'search-index.json';

(function () {
  const root = document.documentElement;

  // 1. Theme Persistence & Switcher (`auto` -> `dark` -> `light`)
  const savedTheme = localStorage.getItem('rsh-doc-theme');
  if (savedTheme === 'light' || savedTheme === 'dark') {
    root.setAttribute('data-doc-theme', savedTheme);
  }
  const themeBtn = document.getElementById('rsh-theme-toggle');
  function syncThemeLabel() {
    if (!themeBtn) return;
    const cur = root.getAttribute('data-doc-theme') || 'auto';
    themeBtn.textContent = cur === 'dark' ? 'Theme: Dark' : (cur === 'light' ? 'Theme: Light' : 'Theme: Auto');
  }
  syncThemeLabel();
  if (themeBtn) {
    themeBtn.addEventListener('click', function () {
      const cur = root.getAttribute('data-doc-theme') || 'auto';
      const next = cur === 'auto' ? 'dark' : (cur === 'dark' ? 'light' : 'auto');
      if (next === 'auto') {
        root.removeAttribute('data-doc-theme');
        localStorage.removeItem('rsh-doc-theme');
      } else {
        root.setAttribute('data-doc-theme', next);
        localStorage.setItem('rsh-doc-theme', next);
      }
      syncThemeLabel();
    });
  }

  // 2. Standalone Mobile Header Toggle Fallback (when raggiesoft-network.js is not loaded)
  const mobBtn = document.querySelector('[data-rs-mobile-toggle]');
  const mobNav = document.getElementById('header-navigation-panel');
  if (mobBtn && mobNav && !window.__rsNetworkInitialized) {
    mobBtn.addEventListener('click', function () {
      if (mobNav.hasAttribute('data-rs-managed')) return;
      const open = mobBtn.getAttribute('aria-expanded') === 'true';
      mobBtn.setAttribute('aria-expanded', String(!open));
      mobNav.classList.toggle('is-open', !open);
    });
  }

  // 3. Left-Rail Instant Table of Contents Filter (RaggieSoft Reference Portal)
  const tocFilter = document.getElementById('rsh-toc-filter');
  if (tocFilter) {
    tocFilter.addEventListener('input', function () {
      const q = tocFilter.value.trim().toLowerCase();
      document.querySelectorAll('.learn-left-rail details.toc-book').forEach(function (book) {
        let anyVisible = false;
        book.querySelectorAll('li[data-toc-item]').forEach(function (li) {
          const hay = (li.getAttribute('data-toc-search') || '').toLowerCase();
          const show = !q || hay.includes(q);
          li.style.display = show ? '' : 'none';
          if (show) anyVisible = true;
        });
        book.style.display = anyVisible ? '' : 'none';
        if (q && anyVisible) book.open = true;
      });
    });
  }

  // 4. Client-Side Code Block Toolbar ("Copy") & Lightweight RaggieScript / Fin# Syntax Highlighter
  function escHtml(s) {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }
  const kwSet = new Set([
    'use','package','showcase','app','param','payload','feature','struct','enum','fn','function',
    'wizard','step','when','install','repair','uninstall','on','let','const','if','elif','else',
    'for','in','while','repeat','until','match','return','break','continue','try','catch','throw',
    'ref','true','false','null','ledger','account','transaction','debit','credit','move','mint'
  ]);
  const tySet = new Set([
    'int','float','bool','string','path','version','array','map','any','void',
    'Capital','Asset','Liability','Equity','Revenue','Expense','USD','EUR','GBP','CAD','JPY'
  ]);

  function highlightCode(raw, lang) {
    if (!lang || (lang !== 'rssc' && lang !== 'raggiescript' && lang !== 'fin' && lang !== 'finsharp' && lang !== 'csharp' && lang !== 'cpp')) {
      return escHtml(raw);
    }
    const tokenRe = /(\/\/[^\n]*|r?"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|v"[0-9.]+"|\b0x[0-9a-fA-F_]+\b|\b[0-9][0-9._]*(?:_USD|_EUR)?\b|\b[A-Za-z_][A-Za-z0-9_]*\b)/g;
    let out = '';
    let last = 0;
    let m;
    while ((m = tokenRe.exec(raw)) !== null) {
      out += escHtml(raw.slice(last, m.index));
      const tok = m[0];
      if (tok.startsWith('//')) {
        out += '<span class="tok-cmt">' + escHtml(tok) + '</span>';
      } else if (tok.startsWith('"') || tok.startsWith('r"') || tok.startsWith("'") || tok.startsWith('v"')) {
        out += '<span class="tok-str">' + escHtml(tok) + '</span>';
      } else if (/^[0-9]/.test(tok)) {
        out += '<span class="tok-num">' + escHtml(tok) + '</span>';
      } else if (kwSet.has(tok)) {
        out += '<span class="tok-kw">' + escHtml(tok) + '</span>';
      } else if (tySet.has(tok)) {
        out += '<span class="tok-ty">' + escHtml(tok) + '</span>';
      } else {
        out += escHtml(tok);
      }
      last = tokenRe.lastIndex;
    }
    out += escHtml(raw.slice(last));
    return out;
  }

  document.querySelectorAll('main.learn-article pre').forEach(function (pre) {
    if (pre.parentElement && pre.parentElement.classList.contains('code-block-shell')) return;
    const codeEl = pre.querySelector('code');
    const rawText = codeEl ? codeEl.textContent : pre.textContent;
    const lang = (pre.getAttribute('data-lang') || '').toLowerCase();

    const shell = document.createElement('div');
    shell.className = 'code-block-shell';
    const bar = document.createElement('div');
    bar.className = 'code-toolbar';
    const label = document.createElement('span');
    label.textContent = lang || 'code';
    const copyBtn = document.createElement('button');
    copyBtn.type = 'button';
    copyBtn.className = 'copy-code-btn';
    copyBtn.textContent = 'Copy';
    copyBtn.addEventListener('click', function () {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(rawText || '').then(function () {
          copyBtn.textContent = 'Copied!';
          setTimeout(function () { copyBtn.textContent = 'Copy'; }, 1600);
        });
      }
    });
    bar.appendChild(label);
    bar.appendChild(copyBtn);
    pre.parentNode.insertBefore(shell, pre);
    shell.appendChild(bar);
    shell.appendChild(pre);
    if (codeEl && lang) {
      codeEl.innerHTML = highlightCode(rawText || '', lang);
    }
  });

  // 5. Right-Rail "In this article" Scroll-Spy (`IntersectionObserver`)
  const outlineLinks = Array.from(document.querySelectorAll('.learn-right-rail .outline-link'));
  if (outlineLinks.length > 0 && 'IntersectionObserver' in window) {
    const byId = new Map();
    outlineLinks.forEach(function (a) {
      const h = a.getAttribute('href') || '';
      if (h.startsWith('#')) byId.set(h.slice(1), a);
    });
    const obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting && byId.has(en.target.id)) {
          outlineLinks.forEach(function (x) { x.classList.remove('is-active'); });
          byId.get(en.target.id).classList.add('is-active');
        }
      });
    }, { rootMargin: '-72px 0px -70% 0px', threshold: 0 });
    byId.forEach(function (_, id) {
      const el = document.getElementById(id);
      if (el) obs.observe(el);
    });
  }

  // 6. `Ctrl+K` / `/` Command-Palette API & Full-Text Search Dialog
  const modal = document.getElementById('rsh-search-modal');
  const openBtn = document.getElementById('rsh-open-search');
  const closeBtn = document.getElementById('rsh-close-search');
  const input = document.getElementById('rsh-modal-input');
  const results = document.getElementById('rsh-modal-results');
  let cachedIndex = null;

  async function ensureIndex() {
    if (cachedIndex) return cachedIndex;
    const res = await fetch(RSH_SEARCH_INDEX_URL);
    cachedIndex = await res.json();
    return cachedIndex;
  }

  function renderHits(q, data) {
    if (!results) return;
    if (!q) {
      results.innerHTML = '<p style="color:var(--muted);font-size:0.9rem;margin:6px 0;">Type a namespace (<code>fs.</code>, <code>msi.</code>, <code>ui.</code>), function name, diagnostic code (<code>RSW701</code>, <code>FIN0001</code>), or keyword.</p>';
      return;
    }
    const symHits = (data.symbols || []).filter(function (s) {
      return s.term.toLowerCase().includes(q) || s.subtitle.toLowerCase().includes(q) || s.category.toLowerCase().includes(q);
    }).slice(0, 10);
    const docHits = (data.topics || []).filter(function (t) {
      return t.title.toLowerCase().includes(q) || t.category.toLowerCase().includes(q) || t.text.includes(q);
    }).slice(0, 8);

    let html = '';
    symHits.forEach(function (s) {
      html += '<a class="search-hit" href="' + escHtml(s.href) + '">' +
              '<div class="search-hit-top"><strong><code>' + escHtml(s.term) + '</code></strong><span class="badge-tag">' + escHtml(s.badge || 'API') + '</span></div>' +
              '<div style="font-size:0.83rem;color:var(--muted);margin-top:3px;">' + escHtml(s.category) + (s.subtitle ? ' &bull; ' + escHtml(s.subtitle) : '') + '</div></a>';
    });
    docHits.forEach(function (d) {
      html += '<a class="search-hit" href="' + escHtml(d.href) + '">' +
              '<div class="search-hit-top"><strong>' + escHtml(d.title) + '</strong><span class="meta-pill">' + escHtml(d.category) + '</span></div>' +
              '<div style="font-size:0.83rem;color:var(--muted);margin-top:3px;">' + escHtml(d.summary) + '</div></a>';
    });
    results.innerHTML = html || '<p style="font-size:0.9rem;">No matching functions, symbols, or articles found.</p>';
  }

  function openSearchModal() {
    if (!modal || typeof modal.showModal !== 'function') return;
    if (!modal.open) modal.showModal();
    if (input) {
      input.focus();
      input.select();
      ensureIndex().then(function (d) { renderHits(input.value.trim().toLowerCase(), d); }).catch(function () {});
    }
  }

  if (openBtn) openBtn.addEventListener('click', openSearchModal);
  if (closeBtn && modal) closeBtn.addEventListener('click', function () { modal.close(); });
  if (modal) {
    modal.addEventListener('click', function (e) {
      if (e.target === modal) modal.close();
    });
  }
  if (input) {
    input.addEventListener('input', function () {
      const q = input.value.trim().toLowerCase();
      ensureIndex().then(function (d) { renderHits(q, d); }).catch(function () {});
    });
  }
  document.addEventListener('keydown', function (e) {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      openSearchModal();
    } else if (e.key === '/' && !['INPUT', 'TEXTAREA', 'SELECT'].includes((document.activeElement && document.activeElement.tagName) || '')) {
      e.preventDefault();
      openSearchModal();
    }
  });

  // 7. Master API Index Client Filter (`api-index`)
  const apiFilter = document.getElementById('rsh-api-master-filter');
  if (apiFilter) {
    apiFilter.addEventListener('input', function () {
      const q = apiFilter.value.trim().toLowerCase();
      document.querySelectorAll('[data-api-row]').forEach(function (row) {
        const hay = (row.getAttribute('data-api-hay') || '').toLowerCase();
        row.style.display = (!q || hay.includes(q)) ? '' : 'none';
      });
    });
  }
})();
